let lang=localStorage.getItem('atelier-lang')||'ka';if(!dict[lang])lang='ka';let filter='all',selected=null,requestData=null;const $=s=>document.querySelector(s), index=()=>({ka:0,en:1,ru:2}[lang]);
function render(){let d=dict[lang];document.documentElement.lang=lang;document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.title=lang==='ka'?'ფერადი — ხელით მოხატული ამბები':lang==='ru'?'Peradi — истории ручной росписи':'Peradi — stories painted by hand';document.querySelectorAll('[data-t]').forEach(el=>{el.innerHTML=d[el.dataset.t]});document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));$('#filters').replaceChildren();[['all',d.all],...groups.map(g=>[g[0],g[index()+1]])].forEach(([key,label])=>{let b=document.createElement('button');b.textContent=label;b.className=filter===key?'active':'';b.onclick=()=>{filter=key;render()};$('#filters').append(b)});$('#catalog').innerHTML='';groups.filter(g=>filter==='all'||g[0]===filter).forEach(g=>{let section=document.createElement('section');section.className='collection';section.innerHTML=`<div class="collection-top"><div><h3>${g[index()+1]}<small>${String(g[4].length).padStart(2,'0')} / ${d.sample}</small></h3></div><div class="arrows"><button aria-label="${d.previous}">←</button><button aria-label="${d.next}">→</button></div></div><div class="track"></div>`;let track=section.querySelector('.track');g[4].forEach(n=>{let card=document.createElement('article');card.className='card';card.innerHTML=`<button class="product" aria-label="${names[n][index()]}"><img src="assets/${String(n).padStart(2,'0')}.webp" alt="${names[n][index()]}" loading="lazy" width="640" height="640"><span>↗</span></button><div class="card-title"><b>${names[n][index()]}</b><span>${String(n+1).padStart(2,'0')}</span></div><p>${d.hand}</p>`;card.querySelector('button').onclick=()=>openDetail(n);track.append(card)});section.querySelectorAll('.arrows button').forEach((b,i)=>b.onclick=()=>{const visible=matchMedia('(max-width:700px)').matches?1:3;const distance=(track.firstElementChild.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap))*visible;const end=track.scrollWidth-track.clientWidth;track.scrollTo({left:i?(track.scrollLeft>=end-5?0:track.scrollLeft+distance):(track.scrollLeft<=5?end:track.scrollLeft-distance),behavior:'smooth'})});$('#catalog').append(section)});let value=$('#object').value;$('#object').innerHTML=d.objects.map((s,i)=>`<option value="${i}">${s}</option>`).join('');$('#object').value=value||'0';$('#idea').placeholder=d.placeholder;if(selected!==null)$('#detailName').textContent=names[selected][index()];if(requestData)showRequest()}
function openDetail(n){selected=n;$('#detailImage').src=`assets/${String(n).padStart(2,'0')}.webp`;$('#detailImage').alt=names[n][index()];$('#detailName').textContent=names[n][index()];$('#modal').showModal()}
$('#close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#choose').onclick=()=>{let n=selected;$('#object').value=n<=2||n===18?'0':n<=5?'1':n<=8||n===19?'2':'3';$('#idea').value=names[n][index()];$('#modal').close();$('#custom').scrollIntoView({behavior:'smooth'});$('#idea').focus({preventScroll:true})};document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('atelier-lang',lang);render()});$('#replay').onclick=()=>{let p=$('#pitch');p.getAnimations({subtree:true}).forEach(a=>{a.cancel();a.play()})};function showRequest(){let d=dict[lang];$('#result').textContent=`${d.requestTitle}\n${d.object}: ${d.objects[requestData.object]}\n${d.design}: ${requestData.idea}`;$('#copy').hidden=false}$('#request').onsubmit=e=>{e.preventDefault();if(!$('#idea').value.trim())return;requestData={object:Number($('#object').value),idea:$('#idea').value.trim()};showRequest()};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#result').textContent);$('#copy').textContent=dict[lang].copied}catch{const range=document.createRange();range.selectNodeContents($('#result'));const sel=getSelection();sel.removeAllRanges();sel.addRange(range)}};render();
